<script setup>
import {computed,inject,ref} from 'vue';
import PageHeader from '../components/PageHeader.vue';import Panel from '../components/Panel.vue';import Empty from '../components/Empty.vue';import Action from '../components/Action.vue';import Badge from '../components/Badge.vue';import Table from '../components/Table.vue';import ResourceActions from '../components/ResourceActions.vue';import DeviceCommands from '../components/DeviceCommands.vue';import {matches,when} from '../format.js';
import {commandLabels,commandNames,commandTone,deviceOnline,remoteAvailable,remoteBlockReason} from '../remote-commands.js';
const {snapshot,ready}=inject('admin'),query=ref(''),filter=ref(''),control=ref(null);
const online=item=>deviceOnline(item,snapshot.value.overview.now);
const blockReason=item=>remoteBlockReason(item,snapshot.value);
const openControl=(item,kind='')=>{control.value={id:item.id,kind};};
const devices=computed(()=>snapshot.value.devices.filter(item=>matches(item,query.value,['id','name','target_name','current_version'])&&(!filter.value||(filter.value==='online'?online(item):filter.value==='revoked'?item.revoked:!online(item)))));
const gateways=computed(()=>snapshot.value.gateways.filter(item=>matches(item,query.value,['id','name'])));
</script>
<template>
 <PageHeader title="设备与网关" description="查看设备连接状态，远程升级固件、重启设备并跟踪执行结果。"><Action kind="device" tone="primary">＋ 添加设备</Action><Action kind="gateway">添加网关</Action></PageHeader>
 <div v-if="!remoteAvailable(snapshot)" class="notice command-backend-notice">远程控制需要更新后的后台。请重启 OTA 服务并刷新此页；现有设备管理仍可使用。</div>
 <div class="resource-toolbar"><div class="search-field"><span>⌕</span><input v-model="query" type="search" placeholder="搜索设备、型号、版本或标识" aria-label="搜索设备"/></div><select v-model="filter" class="filter-select" aria-label="设备状态"><option value="">全部状态</option><option value="online">最近在线</option><option value="offline">离线 / 未联系</option><option value="revoked">凭据已停用</option></select><span class="result-count">{{devices.length}} / {{snapshot.devices.length}} 台设备</span></div>
 <Panel title="设备列表"><Table v-if="devices.length" :columns="['设备','硬件型号','当前版本','通道','连接与执行状态','操作']" kind="device-table"><tr v-for="item in devices" :key="item.id" :data-device-id="item.id"><td><strong>{{item.name}}</strong><small class="mono" :title="item.id">{{item.id.slice(0,20)}}…</small></td><td>{{item.target_name}}<small>{{item.agent_kind==='gateway'?'通过网关':'直接联网'}}</small></td><td>{{item.current_version||'等待上报'}}<small v-if="item.agent_kind==='device'&&item.remote_commands_version!==1">需更新固件以启用远程控制</small></td><td><Badge>{{item.channel}}</Badge></td><td><div class="status-stack"><Badge :tone="item.revoked?'red':online(item)?'green':''">{{item.revoked?'凭据已停用':online(item)?'最近在线':'尚未联系 / 离线'}}</Badge><small>{{when(item.last_seen)}}</small><template v-if="item.latest_command"><Badge :tone="commandTone(item.latest_command)">{{commandNames[item.latest_command.kind]}} · {{commandLabels[item.latest_command.status]||'状态待确认'}}</Badge><small v-if="item.latest_command.error" class="command-cell-error" :title="item.latest_command.error">{{item.latest_command.error}}</small></template></div></td><td><div class="device-actions"><div class="actions device-control-actions"><button type="button" class="primary" data-control-kind="ota.install" :disabled="!ready||!!blockReason(item)" :title="blockReason(item)||'升级到此设备通道的当前发布版本'" @click.stop="openControl(item,'ota.install')">立即升级</button><button type="button" data-control-kind="device.restart" :disabled="!ready||!!blockReason(item)" :title="blockReason(item)||'设备领取指令后重启'" @click.stop="openControl(item,'device.restart')">重启设备</button><button type="button" data-control-kind="history" :disabled="!ready||!remoteAvailable(snapshot)" @click.stop="openControl(item)">控制记录</button></div><div class="actions device-management-actions"><ResourceActions kind="device" :item="item"/><Action kind="channel" :id="item.id">切换通道</Action><template v-if="item.agent_kind==='device'"><Action kind="rotate" :id="item.agent_id">轮换凭据</Action><Action v-if="!item.revoked" kind="revoke" :id="item.agent_id" tone="danger">停用</Action></template></div></div></td></tr></Table><Empty v-else :title="query||filter?'没有匹配的设备':'把第一台设备加入工作区'" description="设备凭据只在创建或轮换时显示一次，请妥善保存。"><Action v-if="!query&&!filter" kind="device" tone="secondary">添加设备</Action></Empty></Panel>
 <p class="form-hint">远程指令由设备联网后主动领取。离线设备可以排队等待，发布固件本身不会立即触发设备升级。</p>
 <Panel title="联网网关"><Table v-if="gateways.length" :columns="['网关','标识','授权子设备','状态','操作']"><tr v-for="item in gateways" :key="item.id"><td><strong>{{item.name}}</strong></td><td class="mono">{{item.id.slice(0,16)}}…</td><td>{{snapshot.devices.filter(device=>device.agent_id===item.id).length}} 台</td><td><Badge :tone="item.revoked?'red':'green'">{{item.revoked?'已停用':'可用'}}</Badge></td><td><div class="actions"><ResourceActions kind="gateway" :item="item"/><Action kind="rotate" :id="item.id">轮换凭据</Action><Action v-if="!item.revoked" kind="revoke" :id="item.id" tone="danger">停用</Action></div></td></tr></Table><Empty v-else title="暂无匹配网关" description="STM32 等设备可通过已适配的 ESP32 或电脑网关接入。"/></Panel>
 <DeviceCommands v-if="control" :key="control.id+control.kind" :device-id="control.id" :kind="control.kind" @close="control=null"/>
</template>
